// Generated by Suite Builder from a crawl of the site. The suite as a zip to hand on: java pack/Pack.java, from the suite's folder.
// EDIT RULES: do not edit this file; regenerating replaces all of it. Account files go in blank; what is left out, and why, is listed when it runs.
import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.time.Instant;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Stream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

/**
 * The suite as a zip to hand on (G-160): java pack/Pack.java from the suite's folder (Java 17; no Maven,
 * nothing to download). Beside the suite, &lt;folder&gt;-pack-&lt;date&gt;.zip, with every account file blank
 * (secrets/*.login), the pages as crawled while the crawl is current (1 days, G-124), and
 * none of what a run leaves or a receiver brings back. It says what it left out, and why.
 */
public final class Pack {
    /** What is left out, by path prefix, and why (the same in every framework Suite Builder writes). */
    static final List<String[]> LEAVES_OUT = List.of(
            new String[] {".git/", "the repository: the receiver keeps their own"},
            new String[] {"target/", "Maven builds it again, and a run's evidence stays with whoever ran it"},
            new String[] {"node_modules/", "npm install brings it back"},
            new String[] {"cypress/failures/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/screenshots/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/videos/", "a run's evidence stays with whoever ran it"},
            new String[] {"cypress/results/", "a run's output"},
            new String[] {"cypress/downloads/", "a run's output"},
            new String[] {"cypress/timings/", "a run's output"},
            new String[] {"cypress/timings-previous/", "a run's output"},
            new String[] {"cypress/report.html", "a run's output"},
            new String[] {"cypress/flaky-tests.txt", "a run's output"},
            new String[] {"cypress/rules-report.md", "a run's output"},
            new String[] {"cypress/link-report.md", "a run's output"});
    static final String BLANK_ACCOUNT = "Username:\nPassword:\n";
    /** The longest path in the zip that still unzips on Windows (260 characters, less room for where it is unzipped). */
    static final int LONGEST_PATH = 160;

    public static void main(String[] args) throws IOException {
        Path suite = Path.of("").toAbsolutePath();
        Path zip = suite.resolveSibling(suite.getFileName() + "-pack-" + LocalDate.now() + ".zip");
        Map<String, Integer> left = new TreeMap<>();
        Map<String, String> why = new TreeMap<>();
        boolean pagesCurrent = crawlIsCurrent(suite);
        int blanked = 0;
        int packed = 0;
        String longest = "";
        try (ZipOutputStream out = new ZipOutputStream(Files.newOutputStream(zip)); Stream<Path> walk = Files.walk(suite)) {
            for (Path file : walk.filter(Files::isRegularFile).sorted().toList()) {
                String rel = suite.relativize(file).toString().replace('\\', '/');
                String reason = leftOut(rel, pagesCurrent);
                if (reason != null) {
                    String group = group(rel);
                    left.merge(group, 1, Integer::sum);
                    why.put(group, reason);
                    continue;
                }
                String entry = suite.getFileName() + "/" + rel;
                if (entry.length() > longest.length()) longest = entry;
                out.putNextEntry(new ZipEntry(entry));
                // Every account file blank, whatever this copy holds: the receiver fills in their own.
                if (rel.startsWith("secrets/") && rel.endsWith(".login")) {
                    out.write(BLANK_ACCOUNT.getBytes(StandardCharsets.UTF_8));
                    blanked++;
                } else {
                    Files.copy(file, (OutputStream) out);
                }
                out.closeEntry();
                packed++;
            }
        }
        System.out.println("Packed " + packed + " files into " + zip + " (" + blanked + " account file" + (blanked == 1 ? "" : "s") + " blank).");
        if (!left.isEmpty()) System.out.println("Left out:");
        left.forEach((group, count) -> System.out.println("  " + group + " (" + count + " file" + (count == 1 ? "" : "s") + "): " + why.get(group)));
        if (longest.length() > LONGEST_PATH) System.out.println("Too long for Windows' zip once unzipped (" + longest.length() + " characters; at most " + LONGEST_PATH + "): " + longest + ". Shorten that name before handing it on.");
        System.out.println("Hand it on as it is; never a copy with a filled account file. The receiver fills in secrets/ (secrets/README.md).");
    }

    /** Why a file stays out of the zip; null when it goes in. */
    static String leftOut(String rel, boolean pagesCurrent) {
        for (String[] out : LEAVES_OUT) if (rel.equals(out[0]) || (out[0].endsWith("/") && rel.startsWith(out[0]))) return out[1];
        if (rel.startsWith("saved-pages/") && (rel.endsWith(".html") || rel.endsWith(".htm"))) return "saved pages can hold personal data: each receiver saves their own";
        if (rel.startsWith("crawl/pages/") && !pagesCurrent) return "the crawl is older than 1 days: crawl again (suite build) to bring them back";
        return null;
    }

    /** What a left-out file is said as: its folder, or itself. */
    static String group(String rel) {
        for (String[] out : LEAVES_OUT) if (rel.startsWith(out[0])) return out[0];
        if (rel.startsWith("saved-pages/")) return "saved-pages/ (the pages; its README goes in)";
        if (rel.startsWith("crawl/pages/")) return "crawl/pages/";
        return rel;
    }

    /** True while the crawl the suite carries is at most 1 days old (crawl/manifest.json). */
    static boolean crawlIsCurrent(Path suite) {
        try {
            String text = Files.readString(suite.resolve("crawl/manifest.json"), StandardCharsets.UTF_8);
            int at = text.indexOf("\"crawlFileSaved\": \"");
            if (at < 0) return false;
            int start = at + "\"crawlFileSaved\": \"".length();
            Instant saved = Instant.parse(text.substring(start, text.indexOf('"', start)));
            return Duration.between(saved, Instant.now()).toDays() <= 1;
        } catch (IOException | RuntimeException e) {
            return false;
        }
    }
}
